<script setup>
import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import PageShell from'../components/PageShell.vue';import StatusPanel from'../components/StatusPanel.vue';import{useMovieStore}from'../stores/movie';import{reportClick,submitRating}from'../api/movie'
const store=useMovieStore(),route=useRoute(),rating=ref(0),hover=ref(0),submitting=ref(false),message=ref(''),loadError=ref('');const movie=computed(()=>store.movies.find(m=>Number(m.movieid)===Number(route.params.id)));const favored=computed(()=>movie.value&&store.favoriteIds.has(Number(movie.value.movieid)));const fallback=e=>{e.target.src='/poster-placeholder.svg';e.target.onerror=null}
async function load(){loadError.value='';try{await store.loadMovies();if(movie.value&&store.user)reportClick(store.user.userid,movie.value.movieid).catch(()=>{})}catch(e){loadError.value=e.message}}
async function rate(){if(!rating.value)return;submitting.value=true;message.value='';try{await submitRating(store.user.userid,movie.value.movieid,rating.value);message.value='评分成功，感谢你的反馈！'}catch(e){message.value=e.message}finally{submitting.value=false}}
onMounted(load)
</script>
<template><PageShell><div v-if="store.loading" class="detail-loading"><div class="skeleton poster-skeleton"></div><div class="skeleton text-skeleton"></div></div><StatusPanel v-else-if="loadError" icon="!" title="详情加载失败" :text="loadError" action="重新加载" @action="load"/><StatusPanel v-else-if="!movie" icon="?" title="没有找到这部电影" text="电影可能已下架或链接不正确"/><section v-else class="detail-page" :style="{'--backdrop':`url(${movie.picture})`}"><div class="detail-backdrop"></div><div class="detail-content"><img class="detail-poster" :src="movie.picture||'/poster-placeholder.svg'" :alt="movie.moviename" @error="fallback"><div class="detail-info"><span class="eyebrow">MOVIE DETAILS</span><h1>{{movie.moviename}}</h1><div class="detail-meta"><strong>★ {{movie.averating.toFixed(1)}}</strong><span>{{movie.releasetime||'上映时间未知'}}</span><span>{{movie.typelist||'未分类'}}</span><span>{{movie.numrating.toLocaleString()}} 人评分</span></div><p class="description">{{movie.description}}</p><dl><div><dt>导演</dt><dd>{{movie.director}}</dd></div><div><dt>主演</dt><dd>{{movie.leadactors}}</dd></div></dl><button class="secondary-button" :class="{favored}" @click="store.toggleFavorite(movie)">{{favored?'♥ 已收藏':'♡ 加入收藏'}}</button></div></div><div class="rating-panel"><div><span class="eyebrow">YOUR RATING</span><h2>为这部电影打分</h2><p>你的评分将帮助系统生成更准确的个性化推荐</p></div><div class="rating-action"><div class="stars" @mouseleave="hover=0"><button v-for="n in 5" :key="n" :class="{active:n<=(hover||rating)}" @mouseenter="hover=n" @click="rating=n">★</button><b>{{rating?rating+'.0':'请选择'}}</b></div><button class="primary-button" :disabled="!rating||submitting" @click="rate">{{submitting?'提交中…':'提交评分'}}</button><span class="rating-message">{{message}}</span></div></div></section></PageShell></template>
